// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { IPriceOracle } from "../core/IPriceOracle.sol";
import { PriceScale } from "./PriceScale.sol";

/// Subset of the Pyth contract used by the adapter.
interface IPyth {
    struct Price {
        int64 price;
        uint64 conf;
        int32 expo;
        uint256 publishTime;
    }

    function getPriceUnsafe(bytes32 id) external view returns (Price memory);
}

/// IPriceOracle backed by Pyth (pull oracle). Pyth only stores what was last pushed, so push
/// fresh data first: fetch updateData from Hermes and call `pyth.updatePriceFeeds{value: fee}`.
/// Hedera testnet Pyth: 0xA2aa501b19aff244D90cc15a4Cf739D2725B5729.
contract PythOracleAdapter is IPriceOracle, Ownable {
    struct Feed {
        bytes32 priceId;
        uint256 maxAge; // seconds
    }

    IPyth public immutable pyth;
    mapping(address asset => Feed) public feeds;

    event FeedSet(address indexed asset, bytes32 priceId, uint256 maxAge);

    constructor(address owner_, IPyth pyth_) Ownable(owner_) {
        pyth = pyth_;
    }

    /// Pass `priceId = 0` to remove the feed.
    function setFeed(address asset, bytes32 priceId, uint256 maxAge) external onlyOwner {
        feeds[asset] = Feed(priceId, maxAge);
        emit FeedSet(asset, priceId, maxAge);
    }

    function getPrice(address asset) external view returns (uint256 price, uint256 updatedAt) {
        Feed memory feed = feeds[asset];
        if (feed.priceId == bytes32(0)) revert NoFeed(asset);

        IPyth.Price memory p = pyth.getPriceUnsafe(feed.priceId);
        // Pyth prices are price * 10^expo with expo <= 0 for USD feeds.
        if (p.price <= 0 || p.expo > 0) revert InvalidPrice(asset);
        updatedAt = p.publishTime;
        // Feed clocks can run a little ahead of Hedera block time (rounded to the record file), e.g. when
        // Pyth is updated and read in the same transaction. Treat a future timestamp as fresh.
        if (updatedAt < block.timestamp && block.timestamp - updatedAt > feed.maxAge) {
            revert StalePrice(asset, updatedAt);
        }

        price = PriceScale.toWad(uint256(uint64(p.price)), uint256(uint32(-p.expo)));
    }
}

contracts/adapters/SaucerSwapAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { HtsAssociation } from "../core/HtsAssociation.sol";
import { ISwapAdapter } from "../core/ISwapAdapter.sol";

/// Subset of the SaucerSwap V1 router (a Uniswap V2 fork) used by the adapter.
interface ISaucerSwapRouter {
    function getAmountsOut(uint256 amountIn, address[] calldata path) external view returns (uint256[] memory);

    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external returns (uint256[] memory amounts);
}

/// ISwapAdapter backed by SaucerSwap V1.
/// Hedera testnet router: 0.0.19264 (0x...4b40). Native HBAR goes through WHBAR (token 0.0.15058).
/// The adapter holds tokens mid-swap, so every HTS token in a path must be associated with it
/// first via `associate`.
contract SaucerSwapAdapter is ISwapAdapter, HtsAssociation, Ownable {
    using SafeERC20 for IERC20;

    ISaucerSwapRouter public immutable router;

    error ZeroAmount();
    error InvalidPath();
    error Expired(uint256 deadline);
    error InsufficientOutput(uint256 amountOut, uint256 minAmountOut);

    event Swapped(
        address indexed caller,
        address indexed tokenIn,
        address indexed tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        address to
    );

    constructor(address owner_, ISaucerSwapRouter router_) Ownable(owner_) {
        router = router_;
    }

    /// Associates the adapter with an HTS token. Idempotent.
    function associate(address token) external onlyOwner {
        _associate(token);
    }

    function quote(uint256 amountIn, address[] calldata path) external view returns (uint256) {
        if (path.length < 2) revert InvalidPath();
        uint256[] memory amounts = router.getAmountsOut(amountIn, path);
        return amounts[amounts.length - 1];
    }

    function swap(
        uint256 amountIn,
        uint256 minAmountOut,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external returns (uint256 amountOut) {
        if (amountIn == 0) revert ZeroAmount();
        if (path.length < 2) revert InvalidPath();
        if (block.timestamp > deadline) revert Expired(deadline);

        IERC20 tokenIn = IERC20(path[0]);
        tokenIn.safeTransferFrom(msg.sender, address(this), amountIn);
        tokenIn.forceApprove(address(router), amountIn);

        // Measure what `to` actually received: HTS custom fees can make it differ from the router's return.
        IERC20 tokenOut = IERC20(path[path.length - 1]);
        uint256 balanceBefore = tokenOut.balanceOf(to);
        router.swapExactTokensForTokens(amountIn, minAmountOut, path, to, deadline);
        amountOut = tokenOut.balanceOf(to) - balanceBefore;
        // The router checks its own figure; this checks the received amount with one error type across adapters.
        if (amountOut < minAmountOut) revert InsufficientOutput(amountOut, minAmountOut);

        emit Swapped(msg.sender, path[0], path[path.length - 1], amountIn, amountOut, to);
    }
}

contracts/core/HtsAssociation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// Lets a contract associate itself with HTS tokens, which Hedera requires before it can hold them.
abstract contract HtsAssociation {
    address private constant HTS = address(0x167);
    int64 private constant HTS_SUCCESS = 22;
    int64 private constant HTS_TOKEN_ALREADY_ASSOCIATED = 194;

    error AssociationFailed(address token, int64 responseCode);

    event TokenAssociated(address indexed token);

    /// Idempotent: an existing association counts as success.
    function _associate(address token) internal {
        (bool ok, bytes memory result) = HTS.call(
            abi.encodeWithSignature("associateToken(address,address)", address(this), token)
        );
        int64 code = ok && result.length == 32 ? abi.decode(result, (int64)) : int64(-1);
        if (code != HTS_SUCCESS && code != HTS_TOKEN_ALREADY_ASSOCIATED) revert AssociationFailed(token, code);
        emit TokenAssociated(token);
    }
}

