// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// Provider-agnostic token swap. Implemented by the SaucerSwap adapter; consumed by the
/// payments, RWA and flash loan modules so they never talk to a DEX router directly.
/// `path` lists token addresses from input to output (e.g. [SAUCE, WHBAR, USDC]).
/// HTS tokens must be associated with the adapter and with `to` before swapping.
interface ISwapAdapter {
    /// Expected output for `amountIn` along `path`, before slippage.
    function quote(uint256 amountIn, address[] calldata path) external view returns (uint256 amountOut);

    /// Pulls `amountIn` of `path[0]` from the caller (requires approval) and sends the output to `to`.
    /// Reverts if the output is below `minAmountOut` or `block.timestamp > deadline`.
    function swap(
        uint256 amountIn,
        uint256 minAmountOut,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external returns (uint256 amountOut);
}

contracts/integrations/dex-rwa/NavBandSw.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { ISwapAdapter } from "../../core/ISwapAdapter.sol";
import { RwaNavOracle } from "../../modules/rwa/RwaNavOracle.sol";

/// @title NavBandSwap (recipe dex+rwa)
/// @notice Buys RWA units on a DEX only when the price paid stays within `bandBps` above the
/// appraised NAV. Thin RWA pools are easy to move, so the NAV oracle is the reference and the
/// pool only executes. The quote token is assumed to be a USD stablecoin (testnet USDC 0.0.5449).
/// The buyer receives the units directly from the pool, so it must be associated and KYC'd.
contract NavBandSwap {
    using SafeERC20 for IERC20;

    ISwapAdapter public immutable adapter;
    RwaNavOracle public immutable oracle;
    address public immutable rwaToken;
    address public immutable quoteToken;
    uint8 public immutable rwaDecimals;
    uint8 public immutable quoteDecimals;
    /// NAV older than this (seconds) is refused.
    uint256 public immutable maxNavAge;
    /// Largest premium over NAV a buyer pays, in basis points.
    uint16 public immutable bandBps;

    event BoughtNearNav(address indexed buyer, uint256 quoteIn, uint256 rwaOut, uint256 navPerUnit, int256 premiumBps);

    error NoLiquidity();
    error AboveNavBand(int256 premiumBps, uint16 bandBps);

    constructor(
        ISwapAdapter adapter_,
        RwaNavOracle oracle_,
        address rwaToken_,
        uint8 rwaDecimals_,
        address quoteToken_,
        uint8 quoteDecimals_,
        uint256 maxNavAge_,
        uint16 bandBps_
    ) {
        adapter = adapter_;
        oracle = oracle_;
        rwaToken = rwaToken_;
        rwaDecimals = rwaDecimals_;
        quoteToken = quoteToken_;
        quoteDecimals = quoteDecimals_;
        maxNavAge = maxNavAge_;
        bandBps = bandBps_;
    }

    /// What `quoteIn` buys right now and how far the effective price sits from NAV
    /// (positive = premium, negative = discount), in basis points.
    function previewBuy(uint256 quoteIn) public view returns (uint256 rwaOut, uint256 nav, int256 premiumBps) {
        rwaOut = adapter.quote(quoteIn, _path());
        if (rwaOut == 0) revert NoLiquidity();
        nav = oracle.navPerUnit(maxNavAge);
        // USD paid per whole RWA unit, 18 decimals.
        uint256 paid = (quoteIn * 10 ** (18 - quoteDecimals) * 10 ** rwaDecimals) / rwaOut;
        premiumBps = ((int256(paid) - int256(nav)) * 10_000) / int256(nav);
    }

    function buy(uint256 quoteIn, uint256 minRwaOut, uint256 deadline) external returns (uint256 rwaOut) {
        (, uint256 nav, int256 premiumBps) = previewBuy(quoteIn);
        if (premiumBps > int256(uint256(bandBps))) revert AboveNavBand(premiumBps, bandBps);

        IERC20(quoteToken).safeTransferFrom(msg.sender, address(this), quoteIn);
        IERC20(quoteToken).forceApprove(address(adapter), quoteIn);
        rwaOut = adapter.swap(quoteIn, minRwaOut, _path(), msg.sender, deadline);
        emit BoughtNearNav(msg.sender, quoteIn, rwaOut, nav, premiumBps);
    }

    function _path() internal view returns (address[] memory path) {
        path = new address[](2);
        path[0] = quoteToken;
        path[1] = rwaToken;
    }
}

contracts/interfaces/IHederaTokenService.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.0;

/// Minimal interface for the HTS precompile at 0x167 (create fungible token + mint).
/// Struct layout matches the official IHederaTokenService for ABI compatibility.
interface IHederaTokenService {
    struct Expiry {
        int64 second;
        address autoRenewAccount;
        int64 autoRenewPeriod;
    }

    struct KeyValue {
        bool inheritAccountKey;
        address contractId;
        bytes ed25519;
        bytes ECDSA_secp256k1;
        address delegatableContractId;
    }

    struct TokenKey {
        uint256 keyType;
        KeyValue key;
    }

    struct HederaToken {
        string name;
        string symbol;
        address treasury;
        string memo;
        bool tokenSupplyType;
        int64 maxSupply;
        bool freezeDefault;
        TokenKey[] tokenKeys;
        Expiry expiry;
    }

    /// Creates a Fungible Token with the specified properties.
    /// @return responseCode SUCCESS is 22.
    /// @return tokenAddress The created token's address.
    function createFungibleToken(
        HederaToken memory token,
        int64 initialTotalSupply,
        int32 decimals
    ) external payable returns (int64 responseCode, address tokenAddress);

    /// Mints an amount of the token to the treasury account.
    /// @param metadata For NFTs only; use empty array for fungible.
    /// @return responseCode SUCCESS is 22.
    function mintToken(
        address token,
        int64 amount,
        bytes[] memory metadata
    ) external returns (int64 responseCode, int64 newTotalSupply, int64[] memory serialNumbers);

    /// Transfers `amount` of a fungible token. Sender must sign or be the calling contract.
    function transferToken(
        address token,
        address sender,
        address recipient,
        int64 amount
    ) external returns (int64 responseCode);

    /// Grants KYC for `account` on `token`. The caller must hold the token's KYC key.
    function grantTokenKyc(address token, address account) external returns (int64 responseCode);

    /// Revokes KYC for `account` on `token`. The caller must hold the token's KYC key.
    function revokeTokenKyc(address token, address account) external returns (int64 responseCode);

    /// @return responseCode SUCCESS is 22.
    /// @return kycGranted Whether `account` has KYC on `token`.
    function isKyc(address token, address account) external returns (int64 responseCode, bool kycGranted);
}

